 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    # Recover large, nearly solid rectangles of non-background color. Noise
    # cells within a rectangle are treated as holes; isolated specks vanish.
    for color in set(v for row in grid for v in row if v != bg):
        best = None
        for r0 in range(h):
            counts = [0] * w
            for r1 in range(r0, h):
                for c in range(w):
                    counts[c] += (grid[r1][c] == color)
                height = r1 - r0 + 1
                if height < 2:
                    continue
                for c0 in range(w):
                    n = 0
                    for c1 in range(c0, w):
                        n += counts[c1]
                        width = c1 - c0 + 1
                        area = height * width
                        if width >= 3 and area >= 10 and n / area >= 0.80:
                            cand = (area, n / area, r0, r1, c0, c1)
                            if best is None or cand[:2] > best[:2]:
                                best = cand
        if best:
            _, _, r0, r1, c0, c1 = best
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
    return out
